            int sum = 0;
            for (int k = 1; k <= i; ++k) {
                sum += abs(j - k);
            }
            V[i] = (V[i] + 1ll * V[j - 1] * num[i - j] % P * (i + 1) % P * C[i - 1][j - 1] +
                    1ll * V[i - j] * num[j - 1] % P * (i + 1) % P * C[i - 1][j - 1] +
                    1ll * num[i - j] * num[j - 1] % P * sum % P * C[i - 1][j - 1]) % P;
        }
